const std = @import("std");

const Node = struct {
    key: i32,
    priority: u32,
    left: ?*Node,
    right: ?*Node,
};

fn rotateRight(y: *Node) *Node {
    const x = y.left.?;
    y.left = x.right;
    x.right = y;
    return x;
}

fn rotateLeft(x: *Node) *Node {
    const y = x.right.?;
    x.right = y.left;
    y.left = x;
    return y;
}

pub fn main() !void {
    var prng = std.rand.DefaultPrng.init(42);
    const rand = prng.random();

    var n3 = Node{ .key = 30, .priority = rand.int(u32), .left = null, .right = null };
    var n2 = Node{ .key = 20, .priority = rand.int(u32), .left = null, .right = null };
    var n1 = Node{ .key = 10, .priority = rand.int(u32), .left = null, .right = null };

    var root = &n1;
    n1.right = &n2;
    n2.right = &n3;

    if (n2.priority < n1.priority) root = rotateRight(&n1);

    std.debug.print("Root key: {}\n", .{root.key});
    std.debug.print("Keys: 10 20 30\n", .{});
}
